I use playwright to "buscar "mochila"", async ({ page }) => {
                                  const campo = page.locator(SELECTORES.campoBusqueda).first();

                                  for (let intento = 1; intento <= 3; intento++) {
                                    await campo.click();
                                    await campo.fill(producto);

                                    if ((await campo.inputValue()) !== producto) continue;

                                    await campo.press('Enter');
                                    try {
                                      await page.waitForURL(/[?&]s=/, { timeout: 8000 });
                                      return;
                                    } catch (e) {
                                      // el header se re-renderizó y perdió el input; reintentar
                                      console.warn(`[SearchPage] Intento ${intento}/3 falló para "${producto}"; reintentando`)
                                    }
                                  }

                                  throw new Error(`No se pudo ejecutar la búsqueda de "${producto}" tras 3 intentos`);
                                }

I use playwright to "esperar a que la PLP renderice", async ({ page }) => {
                                  try {
                                    await page.waitForSelector(selector, { state: 'attached', timeout: 20000 })
                                  } catch (e) {
                                    console.warn(`[ResultsPage] PLP no detectada en 20s; continuando. ${e.message}`)
                                    await page.waitForLoadState('domcontentloaded')
                                  }
                                }

I use playwright to "abrir /tienda/pdp/mochila-casual-unisex/1187410696", async ({ page }) => {
                                  let ultimoError

                                  for (let intento = 1; intento <= INTENTOS_NAVEGACION; intento++) {
                                    try {
                                      await page.goto(destino, { waitUntil: 'domcontentloaded' })
                                      return
                                    } catch (error) {
                                      ultimoError = error
                                      if (!ERRORES_REINTENTABLES.test(error.message)) throw error
                                    }
                                  }

                                  throw new Error(
                                    `No se pudo abrir ${destino} tras ${INTENTOS_NAVEGACION} intentos. ` +
                                      `Último error: ${ultimoError.message}`
                                  )
                                }

I use playwright to "leer la descripción del producto", async ({ page }) => {
                                  const bloques = await page.locator(SELECTORES.descripcion).allTextContents()
                                  const candidato = bloques
                                    .map((t) => t.trim())
                                    .find((t) => t.length >= LARGO_MINIMO_DESCRIPCION)

                                  if (candidato) return candidato

                                  const encabezado = page.getByText(/descripci[óo]n/i).first()
                                  if ((await encabezado.count()) > 0) {
                                    const contenedor = encabezado.locator('xpath=..')
                                    return (await contenedor.innerText()).trim()
                                  }

                                  return ''
                                }
